// AI Build preview — the Founder's view of a website being generated by Node 1.
//
// Everything here reads real build records: build_jobs for status, build_cycles for what each review cycle decided,
// build_revisions for the stored website of each revision, and the quality scorecard for certification. Nothing is
// synthesised. A revision only appears once the runner has actually stored it, so the history can never show a cycle
// that has not happened.
//
// The embedded preview is the generated frontend itself, served from the snapshot through
// /staff/builds/:id/rev/:rev/* with a sandboxing CSP. The generated BACKEND is deliberately not deployed here, so
// the page says so plainly and shows the runner's own backend evidence (gates C/D/E and the persistence check)
// rather than implying a form will submit.
import type { Router } from "../lib/router.ts";
import type { AppContext } from "../app/context.ts";
import { html, formatDateTime, type SafeHtml } from "../lib/html.ts";
import { requireStaff } from "../app/app.ts";
import { BUILD_STATE_LABELS, type BuildState } from "../domain/builds.ts";
import { alert, badge, dl, emptyState, kpi, linkButton, pageHead, table } from "../ui/components.ts";
import { staffPage } from "./crm.ts";
import * as B from "../services/builds.ts";
import * as BR from "../services/build-revisions.ts";
import { latestQuality } from "../services/build-quality.ts";
import { selectionForJob } from "../services/design-gallery.ts";

const VIEWPORTS = { desktop: { w: 1440, h: 900, label: "Desktop" }, tablet: { w: 820, h: 1180, label: "Tablet" }, mobile: { w: 390, h: 844, label: "Mobile" } } as const;
type ViewportName = keyof typeof VIEWPORTS;

/** Builds that are still moving: the page polls while one of these is true, and not otherwise. */
const ACTIVE: BuildState[] = ["queued", "preparing", "building", "verifying"];

const revKey = (r: { attempt: number; cycle: number }) => `${r.attempt}-${r.cycle}`;
/** build_revisions.score: the reviewer's quality mark for a stored website, already on a 0-10 scale. */
const score = (n: number | null | undefined) => (n === null || n === undefined ? "—" : `${n.toFixed(1)}/10`);
/**
 * build_cycles.score is a DIFFERENT measure on a DIFFERENT scale: progressScore(), a 0-1 fraction of the cycle's
 * checks that passed (src/services/build-pipeline.ts). Both were rendered through score() above, so a cycle that
 * passed everything was reported to the Founder as "1.0/10" beside a revision's "9.4/10" -- two unrelated numbers
 * dressed as the same one, in the page where the score is supposed to be reconciled. The builds list already
 * showed this value as a percentage; this agrees with it.
 */
const cycleScore = (n: number | null | undefined) => (n === null || n === undefined ? "—" : `${Math.round(n * 100)}% of checks`);

function elapsed(from: string, to: string | null): string {
  const ms = (to ? Date.parse(to) : Date.now()) - Date.parse(from);
  if (!Number.isFinite(ms) || ms < 0) return "—";
  const m = Math.floor(ms / 60000);
  return m < 60 ? `${m} min` : `${Math.floor(m / 60)} h ${m % 60} min`;
}

/** A revision's label in the history: what produced it, not an invented version number. */
function revLabel(r: BR.RevisionRow): string {
  if (r.cycle === 0) return "Initial generated website";
  return `${r.phase === "repair" ? "Repair" : r.phase === "final" ? "Final" : "Build"} after review cycle ${r.cycle}`;
}

function viewportOf(ctx: AppContext): ViewportName {
  const v = ctx.url.searchParams.get("vp") ?? "desktop";
  return (v in VIEWPORTS ? v : "desktop") as ViewportName;
}

/** The embedded website, at one viewport. The iframe is sandboxed by the served document's own CSP as well. */
function frame(src: string, vp: ViewportName, title: string): SafeHtml {
  const { w, h } = VIEWPORTS[vp];
  return html`<div class="preview-frame" style="max-width:100%;overflow:auto">
<iframe src="${src}" title="${title}" width="${String(w)}" height="${String(h)}" loading="lazy"
  style="width:${String(w)}px;height:${String(h)}px;max-width:100%;border:1px solid var(--line,#ccc);background:#fff"
  referrerpolicy="no-referrer" sandbox="allow-scripts allow-forms allow-popups"></iframe></div>`;
}

function viewportLinks(base: string, current: ViewportName): SafeHtml {
  return html`<p class="row">${Object.entries(VIEWPORTS).map(([name, v]) =>
    name === current
      ? badge("info", `${v.label} ${v.w}×${v.h}`)
      : linkButton(`${v.label} ${v.w}×${v.h}`, `${base}&vp=${name}`, "ghost", "sm"))}</p>`;
}

export function register(r: Router): void {
  r.get("/staff/builds/:id/inspect", async (ctx, p) => {
    requireStaff(ctx, "builds.read");
    const d = await B.buildDetail(ctx.db, p.id);
    const j = d.job;
    const revisions = await BR.listRevisions(ctx.db, j.id);
    const cycles = (await ctx.db.prepare(`SELECT cycle, decision, decision_reason, score, builder_model, reviewer_model, next_prompt, findings_json, created_at
      FROM build_cycles WHERE job_id = ? ORDER BY cycle`).bind(j.id).all<{ cycle: number; decision: string | null; decision_reason: string | null; score: number | null; builder_model: string | null; reviewer_model: string | null; next_prompt: string | null; findings_json: string | null; created_at: string }>()).results;
    const q = await latestQuality(ctx.db, j.id);
    const gallery = await selectionForJob(ctx.db, j.id);
    const vp = viewportOf(ctx);
    const active = ACTIVE.includes(j.state as BuildState);

    // Which revision is on screen: the one asked for, else the best the ratchet kept, else the newest stored.
    const asked = ctx.url.searchParams.get("rev");
    const best = revisions.find((x) => x.is_best === 1);
    const current = revisions.find((x) => revKey(x) === asked) ?? best ?? revisions[revisions.length - 1] ?? null;
    const compareTo = revisions.find((x) => revKey(x) === ctx.url.searchParams.get("cmp")) ?? null;
    const page = ctx.url.searchParams.get("page") ?? "";
    const detail = current ? await BR.revisionDetail(ctx.db, j.id, current.attempt, current.cycle) : null;
    const pages = (detail?.files ?? []).filter((f) => f.kind === "page").map((f) => f.path);
    const shots = (detail?.files ?? []).filter((f) => f.kind === "screenshot").map((f) => f.path);
    // Every stored file -- the framed website, the screenshots, the file list -- is served through ONE mechanism:
    // a signed capability in the URL. There used to be a second, cookie-authenticated route, and it could only ever
    // produce the bug this page exists to show: a sandboxed document has an opaque origin, so the browser withholds
    // the SameSite=Lax session cookie from every request that document makes, and the stylesheet was redirected to
    // the sign-in page. Opening index.html from the file list hit exactly that. BR.previewToken has the measurements.
    // Minted here, behind requireStaff, once per page load.
    const tokens = new Map<string, string>();
    for (const rev of revisions) {
      const t = await BR.previewToken(ctx.env, j.id, rev.attempt, rev.cycle);
      if (t) tokens.set(revKey(rev), t);
    }
    const renderFor = (rev: BR.RevisionRow, path = "") =>
      `/build-preview/${j.id}/${revKey(rev)}/${tokens.get(revKey(rev)) ?? ""}/${path || "index.html"}`;
    const base = current ? `/staff/builds/${j.id}/inspect?rev=${revKey(current)}${page ? `&page=${encodeURIComponent(page)}` : ""}${compareTo ? `&cmp=${revKey(compareTo)}` : ""}` : `/staff/builds/${j.id}/inspect?`;
    const latestCycle = cycles[cycles.length - 1] ?? null;

    const head = html`${pageHead(`AI build preview — ${d.summary.organizationName}`,
      linkButton("Build record", `/staff/builds/${j.id}`, "ghost", "sm"), "The website Node 1 is generating, revision by revision")}
${active ? alert("info", html`This build is running: the page refreshes itself every 20 seconds. ${badge("info", BUILD_STATE_LABELS[j.state as BuildState])}`) : ""}
<section class="card"><h2 class="card__title">This build</h2>
<div class="kpis">
  ${kpi("Status", BUILD_STATE_LABELS[j.state as BuildState], j.state_reason ?? undefined)}
  ${kpi("Package", String(j.package_id ?? "—"), j.kind === "revision" ? `revision ${j.revision}` : "first build")}
  ${kpi("Review cycles", String(cycles.length), latestCycle ? `latest: ${latestCycle.decision ?? "—"}` : "none yet")}
  ${kpi("Elapsed", elapsed(j.created_at, ACTIVE.includes(j.state as BuildState) ? null : j.updated_at), `attempt ${j.attempts}`)}
  ${kpi("Latest cycle", cycleScore(latestCycle?.score ?? null), "checks passed in the newest review cycle")}
  ${kpi("Best verified", score(best?.score ?? null), best ? revLabel(best) : "no verified revision yet")}
  ${kpi("Revisions stored", String(revisions.length), "inspectable below")}
  ${kpi("Certification", q ? (q.eligible ? "Eligible" : q.waiting_external ? "Waiting on customer setup" : "Not eligible") : "No scorecard yet", q ? `${q.score}/10 · ${q.passed}/${q.applicable} criteria` : undefined)}
</div>
${dl([["Builder job", html`<code>${j.id}</code>`], ["Order", j.order_id ? html`<code>${j.order_id}</code>` : "—"],
  ["Builder model", latestCycle?.builder_model ?? "—"], ["Reviewer model", latestCycle?.reviewer_model ?? "—"],
  ["Acceptance verdict", j.ai_acceptance ?? "not decided"], ["Source commit", j.source_commit ? html`<code>${j.source_commit.slice(0, 12)}</code>` : "—"]])}
</section>`;

    if (!current || !detail) {
      return staffPage(ctx, "AI build preview", html`${head}
<section class="card"><h2 class="card__title">Website preview</h2>
${emptyState("No revision stored yet", active
  ? "Node 1 stores a snapshot of the website as soon as the first build phase finishes. This page will show it once that happens."
  : "This build stored no website snapshot. Builds that ran before the preview system existed, or that failed before generating a site, have nothing to show here.")}
</section>`);
    }

    const body = html`${head}
<section class="card"><h2 class="card__title">Website preview — ${revLabel(current)}</h2>
<p class="faint">The generated frontend itself, served from the stored snapshot. Its URLs are pointed at this preview's
 path so the stylesheet and in-page links work; the stored bytes are unchanged and every file is listed below.
 The generated <strong>backend is not deployed here</strong>, so forms will not submit in this frame — what the backend
 actually does is evidenced by the runner's gates and persistence check on the build record.</p>
${current.reverted ? alert("warn", html`<strong>This revision was rolled back by the repair ratchet.</strong> ${current.reverted_reason ?? ""}`) : ""}
${current.is_best ? alert("success", "This is the best verified revision the build reached.") : ""}
${tokens.size ? "" : alert("error", html`<strong>The website below cannot be rendered.</strong> Serving a sandboxed
 preview needs a signing secret, and neither <code>BUILD_PREVIEW_FILE_SECRET</code> nor <code>BUILD_RUNNER_SECRET</code>
 is configured on this environment. The stored files are still listed below and can be opened individually.`)}
<p class="row">${linkButton("Open in a new tab", renderFor(current, page), "secondary", "sm")}
 ${linkButton("Refresh", `${base}&t=${String(Date.now())}`, "ghost", "sm")}
 ${revisions.length > 1 ? linkButton(compareTo ? "Stop comparing" : "Compare with another revision", compareTo ? base.replace(/&cmp=[^&]*/, "") : `${base}&cmp=${revKey(revisions.find((x) => revKey(x) !== revKey(current))!)}`, "ghost", "sm") : ""}</p>
${viewportLinks(base, vp)}
${pages.length > 1 ? html`<p class="row"><span class="faint">Pages:</span> ${pages.map((pg) =>
  (page || "index.html") === pg ? badge("info", pg) : linkButton(pg, `/staff/builds/${j.id}/inspect?rev=${revKey(current)}&vp=${vp}&page=${encodeURIComponent(pg)}${compareTo ? `&cmp=${revKey(compareTo)}` : ""}`, "ghost", "sm"))}</p>` : ""}
${compareTo
  ? html`<div class="grid grid--2">
<div><h3>${revLabel(current)} · ${score(current.score)}</h3>${frame(renderFor(current, page), vp, `${revLabel(current)} preview`)}</div>
<div><h3>${revLabel(compareTo)} · ${score(compareTo.score)}</h3>${frame(renderFor(compareTo, page), vp, `${revLabel(compareTo)} preview`)}</div>
</div>
${alert(current.score !== null && compareTo.score !== null ? (current.score > compareTo.score ? "success" : current.score < compareTo.score ? "warn" : "info") : "info",
  current.score !== null && compareTo.score !== null
    ? `Quality score: ${score(compareTo.score)} → ${score(current.score)} (${current.score === compareTo.score ? "unchanged" : current.score > compareTo.score ? `+${(current.score - compareTo.score).toFixed(1)} better` : `${(current.score - compareTo.score).toFixed(1)} worse`}).`
    : "One of these revisions has no recorded score, so the two cannot be compared on quality.")}`
  : frame(renderFor(current, page), vp, `${revLabel(current)} preview`)}
</section>

<section class="card"><h2 class="card__title">Revision history</h2>
<p class="faint">Every revision Node 1 stored, oldest first. Snapshots are immutable: a later cycle never overwrites an
 earlier one, so a revision the ratchet rolled back is still here to inspect.</p>
${table(revisions, [
  { header: "Revision", cell: (x) => html`${revLabel(x)}<br><span class="faint">${formatDateTime(x.created_at)}</span>` },
  { header: "Score", cell: (x) => score(x.score) },
  { header: "Decision", cell: (x) => x.decision ?? "—" },
  // A rolled-back revision carries its reason here, not only when it happens to be the one on screen: "show why the
  // repair was rejected" is the whole point of keeping it.
  { header: "State", cell: (x) => html`${x.is_best ? badge("ok", "Best verified") : ""} ${x.reverted ? badge("bad", "Rolled back") : ""}${!x.is_best && !x.reverted ? badge("muted", "Superseded") : ""}${x.reverted && x.reverted_reason ? html`<br><span class="faint">${x.reverted_reason}</span>` : ""}` },
  { header: "Files", cell: (x) => `${x.file_count} (${Math.round(x.total_bytes / 1024)} KB)` },
  { header: "", cell: (x) => html`${revKey(x) === revKey(current) ? badge("info", "Shown") : linkButton("Inspect", `/staff/builds/${j.id}/inspect?rev=${revKey(x)}&vp=${vp}`, "ghost", "sm")}
 ${revKey(x) === revKey(current) ? "" : linkButton("Compare", `/staff/builds/${j.id}/inspect?rev=${revKey(current)}&vp=${vp}&cmp=${revKey(x)}`, "ghost", "sm")}` },
], { empty: emptyState("No revisions", "Nothing stored yet.") })}
</section>

${shots.length ? html`<section class="card"><h2 class="card__title">Screenshots the reviewer saw — ${revLabel(current)}</h2>
<p class="faint">Captured by the runner's headless browser during this cycle. These are what the vision reviewer judged.</p>
<div class="grid grid--2">${shots.map((s) => html`<figure><img src="${renderFor(current, s)}" alt="${s}" loading="lazy" style="max-width:100%;border:1px solid var(--line,#ccc)"><figcaption class="faint">${s.replace(".crestmont/screenshots/", "")}</figcaption></figure>`)}</div>
</section>` : ""}

<section class="card"><h2 class="card__title">What this revision contains</h2>
<p class="faint">The stored bytes, exactly as the builder wrote them. Opening a file shows the original; the preview above is the same bytes with its URLs pointed at this path.</p>
${table(detail.files, [
  { header: "Path", cell: (f) => html`<a href="${renderFor(current, f.path)}"><code>${f.path}</code></a>` },
  { header: "Kind", cell: (f) => f.kind },
  { header: "Type", cell: (f) => f.content_type.split(";")[0] },
  { header: "Size", cell: (f) => `${Math.max(1, Math.round(f.size_bytes / 1024))} KB` },
], { empty: emptyState("No files", "This revision stored no files.") })}
</section>

<section class="card"><h2 class="card__title">Design references this build saw</h2>
<p class="faint">The AI draws design quality from the one approved gallery, and what it was shown is recorded against
 the job with the gallery version at the time. An empty list means the builder designed this website with no approved
 benchmark to work from.</p>
${gallery.length
  ? table(gallery, [{ header: "Reference", cell: (g) => g.title }, { header: "Gallery version", cell: (g) => String(g.gallery_version) },
      { header: "Shown at", cell: (g) => formatDateTime(g.selected_at) }])
  : alert("warn", "No approved design reference was available when this build ran, so it had no benchmark to design against. The gallery needs approved references before a build can be held to a design standard.")}
</section>

<section class="card"><h2 class="card__title">Review and repair history</h2>
<p class="faint">The reviewer's decision for each cycle and the corrective prompt it produced. Findings are the reviewer's own words.</p>
${table(cycles, [
  { header: "Cycle", cell: (c) => String(c.cycle) },
  { header: "When", cell: (c) => formatDateTime(c.created_at) },
  { header: "Decision", cell: (c) => html`${badge(c.decision === "ESCALATED" ? "bad" : /^READY_/.test(c.decision ?? "") ? "ok" : "info", c.decision ?? "—")}<br><span class="faint">${c.decision_reason ?? ""}</span>` },
  { header: "Checks passed", cell: (c) => cycleScore(c.score) },
  { header: "Models", cell: (c) => html`<span class="faint">builder</span> ${c.builder_model ?? "—"}<br><span class="faint">reviewer</span> ${c.reviewer_model ?? "—"}` },
  { header: "Findings", cell: (c) => {
      const f = ((): string[] => { try { const v = JSON.parse(c.findings_json ?? "{}") as { outstanding?: string[] }; return Array.isArray(v.outstanding) ? v.outstanding : []; } catch { return []; } })();
      return f.length ? html`<details><summary>${String(f.length)} outstanding</summary><ul>${f.slice(0, 20).map((x) => html`<li>${x}</li>`)}</ul></details>` : "—";
    } },
], { empty: emptyState("No review cycles", "The build has not completed a review cycle yet.") })}
</section>`;

    const page404 = page && !pages.includes(page) ? alert("warn", `This revision has no page "${page}"; showing its home page instead.`) : "";
    return staffPage(ctx, "AI build preview", html`${page404}${body}${active ? html`<meta http-equiv="refresh" content="20">` : ""}`);
  });

}
